// Dashboard warning lights. Icons are simple original line drawings (viewBox 0 0 48 48, stroke = currentColor).
// color: red (stop/serious), amber (check soon), green/blue (information).
// sev: stop | soon | check | info
module.exports = [
{"id":"check-engine-light","name":"Check engine light","aka":["Service engine soon","Engine malfunction light","MIL"],"color":"amber","sev":"soon","icon":"<path d=\"M14 18H34L38 22H41V19H44V33H41V30H38V35H20L16 31H14Z\"/><path d=\"M14 22H9M9 19V31M14 28H9\"/><path d=\"M20 18V14M28 18V14M17 14H31\"/>","meaning":"The engine computer found a problem with the engine, fuel, ignition or emissions system and stored a trouble code.","drive":"Usually yes, for a short while, if the light is steady and the car drives normally. If it's flashing, the engine is misfiring badly: slow down and get it checked right away, because a flashing light can ruin the catalytic converter.","todo":["Check that the gas cap is tight (a loose cap is a common cause).","Notice how the car drives: rough idle, shaking or loss of power make it more urgent.","Get the code read. Many parts stores do it free, then look the code up on our Code lookup."],"causes":["Loose or damaged gas cap","Oxygen sensor or catalytic converter","Misfire from spark plugs or ignition coils","Mass airflow sensor","Evaporative (EVAP) leak"],"guides":["check-engine-light-on","check-engine-light-flashing"],"codes":["P0420","P0300","P0171","P0455","P0442","P0128"]},
{"id":"oil-pressure-light","name":"Oil pressure warning light","aka":["Oil can light","Low oil pressure light"],"color":"red","sev":"stop","icon":"<path d=\"M8 22H14L17 19H25L28 22L42 16L43 18L31 31H11L8 28Z\"/><path d=\"M21 19V16M18 16H24\"/><path d=\"M8 22L4 20V26L8 28\"/><path d=\"M43 25c0 2-1 3.5-2 3.5s-2-1.5-2-3.5 2-4 2-4 2 2 2 4z\"/>","meaning":"Oil pressure has dropped too low to protect the engine. Without pressure, metal parts grind against each other within minutes.","drive":"No. Pull over as soon as it's safe and turn the engine off. Driving even a few miles can destroy the engine.","todo":["Pull over and shut the engine off.","Wait a few minutes, then check the oil level on the dipstick.","If it's low, add the correct oil. If the light stays on after topping up, or the level was fine, have it towed."],"causes":["Low oil level from a leak or burning oil","Failing oil pump or clogged pickup","Faulty oil pressure sensor (switch)","Worn engine bearings"],"guides":["oil-pressure-light-on","burning-oil-low-oil-level","oil-leak"],"codes":["P0520","P0521","P0522","P0524"]},
{"id":"engine-temperature-light","name":"Engine temperature warning light","aka":["Coolant temperature light","Overheating light","Thermometer light"],"color":"red","sev":"stop","icon":"<path d=\"M24 8v20\"/><circle cx=\"24\" cy=\"32\" r=\"5\"/><path d=\"M28 12h5M28 17h5M28 22h5\"/><path d=\"M8 40c3-2 5-2 8 0s5 2 8 0 5-2 8 0 5 2 8 0\"/>","meaning":"The engine is overheating, or the coolant level is too low. If it's blue, the engine is just still cold.","drive":"Not if it's red. Pull over, turn the engine off and let it cool. Driving an overheating engine can warp the cylinder head or blow the head gasket.","todo":["If you can't stop yet, turn the A/C off and the heater on full hot to pull heat away.","Pull over and turn the engine off.","Never open the radiator cap while hot. Once cool, check the coolant level and look for leaks."],"causes":["Low coolant from a leak","Cooling fan not working","Failed thermostat or water pump","Head gasket failure"],"guides":["engine-overheating","overheats-only-in-traffic","losing-coolant-no-visible-leak"],"codes":["P0217","P0128","P0118","P0480"]},
{"id":"battery-light","name":"Battery / charging system light","aka":["Alternator light","Charging light"],"color":"red","sev":"soon","icon":"<rect x=\"8\" y=\"16\" width=\"32\" height=\"22\" rx=\"2\"/><path d=\"M14 16v-4h6v4M28 16v-4h6v4\"/><path d=\"M14 27h6M31 24v6M28 27h6\"/>","meaning":"The charging system isn't keeping the battery charged. The car is running on battery power alone and will die when it runs out.","drive":"Only far enough to get somewhere safe or to a shop, usually 15 to 30 minutes at most. Turn off the radio, A/C and other accessories to stretch it.","todo":["Turn off everything you don't need.","Drive straight to a shop or home; don't shut the engine off on the way if it might not restart.","Have the battery and alternator tested (many parts stores test free)."],"causes":["Failing alternator","Broken or slipping serpentine belt","Loose or corroded battery cables","Worn-out battery"],"guides":["battery-light-on","battery-keeps-dying","headlights-dim-or-flickering"],"codes":["P0562","P0563","P0620","P0622"]},
{"id":"brake-warning-light","name":"Brake system warning light","aka":["BRAKE light","(!) light"],"color":"red","sev":"stop","icon":"<circle cx=\"24\" cy=\"24\" r=\"11\"/><path d=\"M10 14c-3 6-3 14 0 20M38 14c3 6 3 14 0 20\"/><path d=\"M24 17v9\"/><circle cx=\"24\" cy=\"30.5\" r=\"1\" fill=\"currentColor\"/>","meaning":"Either the parking brake is on, or there's a problem with the brakes, most often low brake fluid.","drive":"Release the parking brake first. If the light stays on, don't drive until it's checked. Low brake fluid can mean a leak and brakes that may not stop the car.","todo":["Make sure the parking brake is fully released.","Check the brake fluid level in the reservoir under the hood.","If the pedal feels soft or sinks, don't drive: have it towed."],"causes":["Parking brake on or its switch stuck","Low brake fluid from worn pads or a leak","Brake fluid leak at a line, hose or caliper","ABS or brake booster fault"],"guides":["brake-warning-light-on","brake-fluid-leak","soft-or-spongy-brake-pedal"],"codes":["C0035","C0040"]},
{"id":"abs-light","name":"ABS warning light","aka":["Anti-lock brake light"],"color":"amber","sev":"soon","icon":"<circle cx=\"24\" cy=\"24\" r=\"12\"/><path d=\"M10 14c-3 6-3 14 0 20M38 14c3 6 3 14 0 20\"/><text x=\"24\" y=\"28.5\" font-size=\"11\" font-weight=\"700\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" font-family=\"Arial\">ABS</text>","meaning":"The anti-lock brake system has a fault and is turned off. Your normal brakes still work, but the wheels can lock up in a hard stop.","drive":"Yes, carefully. Leave extra stopping distance, especially on wet or icy roads, and get it checked soon. If the red brake light is on too, stop driving.","todo":["Drive gently and avoid hard stops.","Check the brake fluid level.","Have the ABS codes read; a wheel speed sensor is the usual cause."],"causes":["Faulty wheel speed sensor or damaged wiring","Damaged tone ring on a wheel hub","Low brake fluid","ABS control module or pump fault"],"guides":["abs-light-on"],"codes":["C0035","C0040","C0045","C0050"]},
{"id":"airbag-light","name":"Airbag warning light","aka":["SRS light","Supplemental restraint system light"],"color":"red","sev":"soon","icon":"<circle cx=\"13\" cy=\"10\" r=\"4\"/><path d=\"M14 16L11 29H20L24 41\"/><path d=\"M13 20L20 24\"/><circle cx=\"32\" cy=\"21\" r=\"8\"/>","meaning":"The airbag system found a fault and may not deploy in a crash. Seat belt pretensioners may also be disabled.","drive":"The car drives normally, but you may not have airbag protection. Get it checked soon and check for open airbag recalls with your VIN.","todo":["Check your VIN for airbag recalls (they're fixed free).","Make sure nothing is wedged under the front seats.","Have the airbag codes read by a shop with an SRS-capable scanner."],"causes":["Clock spring in the steering wheel","Seat belt buckle or occupant sensor","Wiring under the seats","Airbag control module"],"guides":["airbag-light-on"],"codes":["B0001","B0012"]},
{"id":"tire-pressure-light","name":"Tire pressure warning light (TPMS)","aka":["TPMS light","Low tire light"],"color":"amber","sev":"check","icon":"<path d=\"M14 12c-4 6-4 18 0 24h20c4-6 4-18 0-24\"/><path d=\"M12 36h24\"/><path d=\"M24 16v10\"/><circle cx=\"24\" cy=\"31\" r=\"1.2\" fill=\"currentColor\"/>","meaning":"One or more tires is low on air. If the light flashes for about a minute and then stays on, a tire pressure sensor has a problem.","drive":"Usually yes, gently, to the nearest air pump. But if a tire looks flat, bulges at the bottom, or the car pulls or feels loose in corners, stop and fit the spare or call for a tow. If the light blinked for a minute before going solid, your pressures may be fine and it is the system that is broken, so check all four by hand.","todo":["Check all four tires with a gauge when they're cold.","Fill to the pressure on the driver's door sticker, not the tire sidewall.","If one keeps losing air, have it checked for a nail or leak."],"causes":["Low tire pressure (cold weather drops pressure)","Slow leak from a nail or bad valve","Dead TPMS sensor battery","Sensor not relearned after a tire rotation"],"guides":["tire-pressure-light-on","tire-keeps-losing-air"],"codes":[]},
{"id":"traction-control-light","name":"Traction / stability control light","aka":["ESC light","Skidding car light","VSC light"],"color":"amber","sev":"check","icon":"<path d=\"M14 25L17 15H31L34 25V31H14Z\"/><path d=\"M15 22H33\"/><path d=\"M17 31v3M31 31v3\"/><path d=\"M8 42c3-4 6 4 9 0M31 42c3-4 6 4 9 0\"/>","meaning":"The traction or stability control system is working, has been switched off, or has a fault. If it flashes while you drive it is doing its job on a slippery road; if it stays on, the system is off or has a fault.","drive":"Yes. If it flashes on slippery roads, ease off the gas. If it stays on, the car drives normally but has less help in a skid; get it checked.","todo":["Make sure the traction control button wasn't pressed off.","If the ABS light is also on, the cause is often a wheel speed sensor.","Have the codes read if it stays on."],"causes":["System switched off","Wheel speed sensor fault","Steering angle sensor needs calibration","Engine fault (check engine light on too)"],"guides":["traction-control-light-on"],"codes":["C0035","C0040","U0121"]},
{"id":"power-steering-light","name":"Power steering warning light","aka":["EPS light","Steering wheel with !"],"color":"amber","sev":"soon","icon":"<circle cx=\"22\" cy=\"24\" r=\"12\"/><circle cx=\"22\" cy=\"24\" r=\"3\"/><path d=\"M10 24h9M25 24h9M22 27v9\"/><path d=\"M40 15v10\"/><circle cx=\"40\" cy=\"30\" r=\"1.2\" fill=\"currentColor\"/>","meaning":"The power steering assist has a fault and may be reduced or off. Steering will feel heavy, especially at low speed.","drive":"You can usually steer, but it takes much more effort. Drive carefully to a shop; avoid it if steering is very heavy.","todo":["Restart the car once; some electric systems reset.","Check for a low battery or charging problem (it can trigger this).","On hydraulic systems, check the power steering fluid."],"causes":["Electric power steering motor or sensor fault","Low battery voltage","Low power steering fluid (hydraulic)","Steering column or wiring problem"],"guides":["power-steering-warning-light","steering-hard-to-turn","power-steering-fluid-leak"],"codes":["C0545","U0131"]},
{"id":"transmission-warning-light","name":"Transmission warning light","aka":["AT temp light","Transmission temperature light","Gear with !"],"color":"amber","sev":"soon","icon":"<circle cx=\"24\" cy=\"24\" r=\"10\"/><path d=\"M24 10v-3M24 41v-3M10 24H7M41 24h-3M14 14l-2-2M36 36l-2-2M14 34l-2 2M36 12l-2 2\"/><path d=\"M24 19v6\"/><circle cx=\"24\" cy=\"29\" r=\"1.2\" fill=\"currentColor\"/>","meaning":"The transmission has a fault or is running too hot. Many cars go into limp mode, staying in one gear to protect themselves.","drive":"If it says the transmission is hot, pull over and let it idle in Park to cool. Otherwise drive gently and get it checked soon; ignoring it can turn a small fix into a new transmission.","todo":["If it's an overheat warning, stop and let it cool.","Check the transmission fluid if your car has a dipstick.","Have the codes read before the problem grows."],"causes":["Overheating from towing or hills","Low or burnt transmission fluid","Solenoid or sensor fault","Internal wear"],"guides":["transmission-warning-light","transmission-slipping","transmission-fluid-leak"],"codes":["P0700","P0218","P0711","P0730"]},
{"id":"coolant-level-light","name":"Low coolant level light","aka":["Coolant level warning"],"color":"amber","sev":"soon","icon":"<path d=\"M12 12h24v8H12z\"/><path d=\"M14 20v16h20V20\"/><path d=\"M16 30c2-2 4-2 6 0s4 2 6 0 4-2 6 0\"/>","meaning":"The coolant in the overflow tank is below the minimum mark. Low coolant leads to overheating.","drive":"Short trips only, while watching the temperature gauge. Top it up as soon as the engine is cool.","todo":["Let the engine cool, then check the coolant tank level.","Top up with the coolant type in your owner's manual.","If it keeps dropping, look for leaks or have a pressure test done."],"causes":["Coolant leak (hose, radiator, water pump)","Head gasket leak","Faulty level sensor"],"guides":["losing-coolant-no-visible-leak","engine-overheating"],"codes":["P2560","P2556"]},
{"id":"low-fuel-light","name":"Low fuel light","aka":["Fuel light","Low gas light","Refuel soon light"],"color":"amber","sev":"info","icon":"<rect x=\"12\" y=\"10\" width=\"16\" height=\"28\" rx=\"2\"/><path d=\"M12 20h16\"/><path d=\"M28 16l6 4v12a2 2 0 0 0 4 0V18l-4-4\"/>","meaning":"You're down to your fuel reserve, usually about 1 to 3 gallons depending on the car.","drive":"Yes, to the nearest gas station. Running out can damage the fuel pump and leave you stranded.","todo":["Head to a gas station soon.","Avoid regularly running the tank this low; fuel cools the pump."],"causes":["The tank is genuinely low on fuel","Worn fuel level sender float inside the tank","Failed in-tank fuel pump and sender module","Broken wire, bad ground or corroded connector at the tank","Instrument cluster or fuel gauge fault"],"guides":[],"codes":["P0460","P0461","P0462"]},
{"id":"seat-belt-light","name":"Seat belt reminder light","aka":["Fasten seat belt light"],"color":"red","sev":"info","icon":"<circle cx=\"20\" cy=\"9\" r=\"4\"/><path d=\"M18 15L15 29H25L29 41\"/><path d=\"M14 17L26 30\"/><path d=\"M30 10V30\"/>","meaning":"A belt the car expects to be latched is not latched. On older cars that means a front seat only, but most cars built since the mid-2010s watch the rear seats as well and will warn you if a rear passenger unbuckles while you are moving. Weight on the front passenger seat, such as a bag or a toolbox, reads as a person and sets it off too. It can also stay on with everyone buckled, which points to a fault in a buckle switch, the passenger seat sensor or the restraint wiring.","drive":"Buckle up. If it stays on with everyone buckled, the buckle switch or seat sensor may be faulty.","todo":["Buckle all front-seat passengers.","Move heavy bags off the passenger seat.","If it stays on, have the buckle switch checked (it can affect airbags too)."],"causes":["Unbuckled seat belt","Item on the passenger seat","Faulty buckle switch or occupant sensor"],"guides":["airbag-light-on"],"codes":[]},
{"id":"master-warning-light","name":"Master warning light","aka":["Triangle with !","General warning light"],"color":"amber","sev":"soon","icon":"<path d=\"M24 8l18 32H6z\"/><path d=\"M24 20v10\"/><circle cx=\"24\" cy=\"35\" r=\"1.3\" fill=\"currentColor\"/>","meaning":"A general alert that comes on with a message in the instrument cluster. It points you to another warning.","drive":"Read the message on the dash first - the message decides, not the triangle. Door ajar, washer fluid, key battery and tire pressure messages are fine to drive with. Anything about oil, engine temperature, brakes or steering means stop somewhere safe. On makes that show a red triangle, treat it as stop and get help.","todo":["Read the message in the gauge cluster or center screen.","Check our guide for the specific light or message it mentions."],"causes":["A door, hood or trunk not fully latched","Low engine oil or a failed oil level sensor","Low tire pressure or a dead tire pressure sensor","Weak key fob battery","Low washer fluid or a stuck float switch","Stability control, ABS or another system fault"],"guides":["dashboard-lights-all-on"],"codes":[]},
{"id":"hybrid-system-light","name":"Check hybrid system / EV warning","aka":["Hybrid warning light","Car with !"],"color":"amber","sev":"soon","icon":"<path d=\"M8 31L12 21H36L40 31V36H8Z\"/><circle cx=\"15\" cy=\"36\" r=\"3\"/><circle cx=\"33\" cy=\"36\" r=\"3\"/><path d=\"M24 4V11\"/><circle cx=\"24\" cy=\"15.5\" r=\"1.2\" fill=\"currentColor\"/>","meaning":"The hybrid or electric drive system found a fault, often with the high-voltage battery, inverter or cooling.","drive":"Usually you can drive slowly to a shop, but power may be limited. If the car shuts down or says to stop, pull over safely.","todo":["Note any messages on the screen.","Check the 12-volt battery; a weak one causes hybrid warnings.","Have it checked by a shop that works on hybrids."],"causes":["High-voltage battery cell fault","Inverter or its cooling pump","Weak 12-volt battery","Battery cooling fan clogged"],"guides":["check-hybrid-system-warning"],"codes":["P0A80","P0A7F"]},
{"id":"security-light","name":"Security / immobilizer light","aka":["Key light","Anti-theft light","Car with lock"],"color":"amber","sev":"check","icon":"<path d=\"M8 28l4-8h24l4 8v6H8z\"/><circle cx=\"15\" cy=\"34\" r=\"3\"/><circle cx=\"33\" cy=\"34\" r=\"3\"/><rect x=\"19\" y=\"8\" width=\"10\" height=\"8\" rx=\"1\"/><path d=\"M21 8V6a3 3 0 0 1 6 0v2\"/>","meaning":"Blinking with the car off is normal: it shows the anti-theft system is armed. If it stays on or flashes and the car won't start, the car doesn't recognize the key.","drive":"If it starts and runs normally, you can drive it locally - but treat every shutdown as a gamble on the next start, so stay near home and keep a tow number handy. If it cranks and will not fire, or fires and dies after a second, try the spare key and then stop using the car.","todo":["Try the spare key.","Replace the key fob battery.","Lock and unlock the doors with the key, then try again."],"causes":["Weak key fob battery","Damaged key chip","Immobilizer or antenna ring fault"],"guides":["security-light-flashing-wont-start"],"codes":["P0513","B2799"]},
{"id":"glow-plug-light","name":"Glow plug light (diesel)","aka":["Coil light","Pre-heat light"],"color":"amber","sev":"check","icon":"<path d=\"M8 16V32M40 16V32\"/><path d=\"M12 24c0-5 4-5 4 0s4 5 4 0 4-5 4 0 4 5 4 0 4-5 4 0 4 5 4 0\"/>","meaning":"On a diesel, the glow plugs are warming the engine before starting. If it flashes or stays on while driving, there's an engine fault.","drive":"Wait for it to go out before starting. If it flashes while driving, get it checked soon.","todo":["Wait for the light to go out, then start.","If hard starting in the cold, have the glow plugs tested."],"causes":["Normal pre-heat","Failed glow plug or relay","Engine fault on some diesels"],"guides":[],"codes":["P0380","P0670","P0671"]},
{"id":"def-light","name":"Low DEF / exhaust fluid light (diesel)","aka":["AdBlue light","DEF light"],"color":"amber","sev":"soon","icon":"<rect x=\"7\" y=\"14\" width=\"34\" height=\"20\" rx=\"4\"/><text x=\"24\" y=\"28.5\" font-size=\"11\" font-weight=\"700\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" font-family=\"Arial\">DEF</text><path d=\"M24 4c0 3-2 4-2 6a2 2 0 0 0 4 0c0-2-2-3-2-6z\"/>","meaning":"The diesel exhaust fluid tank is low, or the DEF system has a fault. Diesels limit speed or won't restart if DEF runs out.","drive":"Yes, but refill DEF soon. If the dash shows a countdown to reduced speed, act quickly.","todo":["Top up with DEF (sold at gas stations and parts stores).","If the warning stays after filling, have the DEF system checked."],"causes":["Low DEF","Bad DEF quality sensor or heater","Clogged DEF injector"],"guides":[],"codes":["P20EE","P204F","P207F","P2047","P2201"]},
{"id":"dpf-light","name":"Diesel particulate filter light","aka":["DPF light"],"color":"amber","sev":"soon","icon":"<rect x=\"10\" y=\"16\" width=\"28\" height=\"16\" rx=\"3\"/><path d=\"M6 24h4M38 24h4\"/><circle cx=\"18\" cy=\"24\" r=\"1.5\" fill=\"currentColor\"/><circle cx=\"24\" cy=\"21\" r=\"1.5\" fill=\"currentColor\"/><circle cx=\"24\" cy=\"27\" r=\"1.5\" fill=\"currentColor\"/><circle cx=\"30\" cy=\"24\" r=\"1.5\" fill=\"currentColor\"/>","meaning":"The diesel particulate filter is filling with soot and needs to clean itself (regenerate).","drive":"Yes. A 20-minute drive at steady highway speed usually lets it clean itself. If it stays on, get it checked before it clogs.","todo":["Take a steady 20-minute highway drive.","If it won't clear, have a shop force a regeneration."],"causes":["Lots of short trips","Faulty pressure sensor","Engine problems making extra soot"],"guides":[],"codes":["P2002","P2463","P244A"]},
{"id":"service-light","name":"Service due / maintenance light","aka":["Wrench light","Maint reqd","Oil life"],"color":"amber","sev":"check","icon":"<path d=\"M30 8a8 8 0 0 0-8 10L10 30a3 3 0 0 0 4 4l12-12a8 8 0 0 0 10-8l-5 3-4-1-1-4z\"/>","meaning":"A mileage or time reminder that routine service is due. On Ford and Lincoln the same wrench symbol means a powertrain fault instead, which is not a reminder and will not reset.","drive":"Yes. Book the service soon. If it's a Ford wrench light with reduced power, get it checked sooner.","todo":["Check the maintenance message or oil life percentage.","Get the service done, then have the reminder reset."],"causes":["Oil and filter change interval reached","Reminder not reset after the last service","A larger scheduled service due at this mileage","Electronic throttle body fault (Ford wrench light)","Accelerator pedal position sensor fault (Ford wrench light)"],"guides":[],"codes":["P2135","P2111"]},
{"id":"door-open-light","name":"Door or hood open light","aka":["Door ajar"],"color":"red","sev":"info","icon":"<path d=\"M8 30l6-12h20l6 12v6H8z\"/><path d=\"M34 18l8-6\"/><circle cx=\"15\" cy=\"36\" r=\"3\"/><circle cx=\"33\" cy=\"36\" r=\"3\"/>","meaning":"A door, the hood or the trunk isn't fully closed.","drive":"Close it fully before driving. If everything is shut and it stays on, a door switch or latch sensor is faulty.","todo":["Close every door, the hood and the trunk firmly.","If it stays on, have the latch switch checked (it can drain the battery)."],"causes":["A door, hood, trunk or fuel flap not fully shut","Worn or stuck door frame plunger switch","Switch inside the door latch has failed","Broken wire in the rubber trunk between door and body","Door out of alignment or a worn striker"],"guides":["battery-keeps-dying"],"codes":[]},
{"id":"key-battery-light","name":"Key fob battery low","aka":["Key not detected"],"color":"amber","sev":"info","icon":"<rect x=\"16\" y=\"8\" width=\"16\" height=\"22\" rx=\"4\"/><circle cx=\"24\" cy=\"16\" r=\"2\"/><path d=\"M24 30v10M24 35h4M24 40h4\"/>","meaning":"The battery in your smart key is weak, or the car can't detect the key.","drive":"Yes. Replace the key battery soon. If the car won't detect the key, hold the fob against the start button.","todo":["Replace the key fob coin battery (often a CR2032 or CR2025).","Hold the key against the start button if it isn't detected.","Try the spare fob to see whether the car or the key is at fault.","If both keys show it, have the car's 12-volt battery and keyless system checked."],"causes":["Worn-out coin battery in the fob","Wrong or poor-quality replacement battery","The fob itself has failed, often after water damage","Weak 12-volt battery in the car","Keyless antenna or receiver fault","Another fob, a phone or a wireless tag held against the key"],"guides":["security-light-flashing-wont-start"],"codes":[]},
{"id":"4wd-light","name":"4WD / AWD warning light","aka":["Service 4WD","AWD light"],"color":"amber","sev":"soon","icon":"<rect x=\"10\" y=\"10\" width=\"28\" height=\"28\" rx=\"3\"/><text x=\"24\" y=\"29\" font-size=\"11\" font-weight=\"700\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" font-family=\"Arial\">4WD</text>","meaning":"The four-wheel or all-wheel drive system has a fault and may be working in two-wheel drive only.","drive":"Yes, on normal roads. Avoid snow, mud or towing until it's checked.","todo":["Note if it came on after a tire change (mismatched tires can trigger it).","Have the codes read."],"causes":["Transfer case actuator or motor","Mismatched tire sizes","Wheel speed sensor","Low fluid in the transfer case or rear differential"],"guides":[],"codes":["C0327","P0835"]},
{"id":"lane-assist-light","name":"Lane keeping / driver assist warning","aka":["Collision warning off","Camera blocked"],"color":"amber","sev":"check","icon":"<path d=\"M12 40l6-32M36 40l-6-32\"/><path d=\"M24 10v4M24 20v4M24 30v4\"/>","meaning":"A driver-assist feature (lane keeping, collision warning, adaptive cruise) is off or can't see, often because a camera or radar sensor is blocked.","drive":"Yes, the car drives normally, but those safety helpers aren't working.","todo":["Clean the windshield in front of the camera and the front grille sensor.","If it stays on, have the system checked; a windshield replacement often needs camera calibration."],"causes":["Dirt, snow or ice on the camera or radar","Camera not calibrated after windshield work","Sensor fault"],"guides":[],"codes":["U0235","U0236"]},
{"id":"high-beam-light","name":"High beam indicator","aka":["Blue headlight symbol"],"color":"blue","sev":"info","icon":"<path d=\"M26 12c8 0 12 5 12 12s-4 12-12 12z\"/><path d=\"M8 14h14M8 20h14M8 26h14M8 32h14\"/>","meaning":"Your high beams are on.","drive":"Yes. Switch to low beams when there's oncoming traffic or you're following another car.","todo":["Dim your lights for oncoming traffic and for cars you are following.","If the blue symbol stays on with the stalk in the low beam position, the headlight switch is the likely fault.","Check both main beams against a wall, because the symbol lights up even when one bulb is dead."],"causes":["High beams switched on","Headlight stalk or switch worn or stuck","Burned out high beam bulb, with the symbol still lit","Blown headlight fuse or failed relay","Automatic high beam camera blocked or faulty"],"guides":["headlights-dim-or-flickering"],"codes":[]},
{"id":"cruise-control-light","name":"Cruise control indicator","aka":["Speedometer with arrow"],"color":"green","sev":"info","icon":"<path d=\"M10 32a14 14 0 1 1 28 0\"/><path d=\"M24 32l7-8\"/><path d=\"M14 38h20\"/>","meaning":"Cruise control is on or set. Amber or flashing can mean the system is unavailable.","drive":"Yes. It's an information light.","todo":["If cruise won't work, check the brake light bulbs; a bad brake switch disables cruise."],"causes":["Cruise control engaged","Brake light switch fault (if cruise won't set)"],"guides":[],"codes":["P0571","P0504"]},
{"id":"blind-spot-light","name":"Blind spot monitor warning light","aka":["BSM light","Blind spot monitor unavailable","BLIS warning light","Service side detection system","BSD light"],"color":"amber","sev":"check","icon":"<path d=\"M16 32h16l-2-9H18z\"/><circle cx=\"20\" cy=\"35\" r=\"2.2\"/><circle cx=\"28\" cy=\"35\" r=\"2.2\"/><path d=\"M38 14a12 12 0 0 1 0 20M43 10a18 18 0 0 1 0 28\"/><path d=\"M10 14a12 12 0 0 0 0 20\"/>","meaning":"The blind spot monitor cannot see. Either the radar sensors behind the rear bumper are covered up, or the system has a fault, so it will not warn you about a car sitting alongside you.","drive":"Yes. Nothing about how the car drives, steers or brakes is affected. You just have no electronic help, so check your mirrors and glance over your shoulder before every lane change.","todo":["Wash the back corners of the bumper and clear off any snow, ice, mud or road salt.","Check the system has not been switched off in the vehicle settings menu.","Drive a few miles and restart the car; messages that say temporarily unavailable usually clear themselves.","If it keeps coming back, have it scanned, and tell the shop about any recent bumper work, hitch or trailer wiring."],"causes":["Mud, snow, ice or road salt over the rear bumper corners","Heavy rain or slush while driving","The system was turned off in the vehicle settings","A sensor knocked out of aim by a parking bump or bumper repair","No recalibration after bumper, body or suspension work","Corroded connector, damaged wiring, or water in the bumper harness","A failed radar sensor or control module"],"guides":[],"codes":[]},
{"id":"brake-pad-wear-light","name":"Brake pad wear light","aka":["Brake pad wear sensor warning","Brake wear indicator","Check brake pads","Brake linings worn","Brake pad warning"],"color":"amber","sev":"soon","icon":"<circle cx=\"24\" cy=\"24\" r=\"9\"/><path d=\"M12 14a16 16 0 0 0 0 20M36 14a16 16 0 0 1 0 20\"/>","meaning":"A sensor in the brake pads reports that the friction material has worn down to its limit. The brakes still work, but the pads are at the end of their life and need replacing.","drive":"Yes, carefully, for a short time. The light comes on with a little material left, not none, so a few hundred miles of gentle driving is normally fine while you get an appointment. Stop driving and get it towed if you hear grinding or metal scraping when you brake, or if the pedal feels different, because that means the pads are gone and stopping distances are getting longer.","todo":["Look at the pads through the wheel spokes: a sliver of material thinner than a stack of two quarters means they are done.","Listen when you brake. A squeal means worn, a grinding or scraping noise means stop driving.","Book brake work now and expect both wheels on that axle to be done together.","Have the wear sensor replaced at the same time, or the light will come straight back."],"causes":["Brake pads worn down to their limit through normal use","Wear sensor not replaced with the last set of pads","Sensor wire cut, pinched or unplugged during a previous brake job","One pad worn fast by a sticking caliper or seized slide pins","Broken wiring or a corroded connector in the sensor circuit","Pads replaced but the service indicator never reset on makes that need it"],"guides":[],"codes":[]},
{"id":"maintenance-required-light","name":"Maintenance required light","aka":["MAINT REQD","Maintenance reqd","Wrench light","Service due reminder","Scheduled maintenance light"],"color":"amber","sev":"check","icon":"<rect x=\"5\" y=\"14\" width=\"38\" height=\"20\" rx=\"5\"/><text x=\"24\" y=\"29\" text-anchor=\"middle\" font-family=\"system-ui,Arial,sans-serif\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\">MAINT</text>","meaning":"A reminder that the car has reached a point in its service schedule, usually an oil change plus a tire rotation and a look over the car. It is a mileage or time counter, not a fault the computer has detected.","drive":"Yes, normally. The car runs the same and nothing is failing, so just book the service. The exception is a Ford or Lincoln wrench light: if that comes on and the car hesitates, loses power or goes into limp mode, treat it as a real fault and get it scanned right away rather than booking an oil change.","todo":["Work out what is actually due: read the message center, then check the odometer against the schedule in the owner's manual.","Check the oil level and the tire pressures yourself while you wait for the appointment.","Book the service, and make sure the reminder is reset once the work is done.","If it is a Ford or Lincoln wrench with any loss of power, skip the above and have the codes read."],"causes":["Mileage or time service interval reached","Oil life monitor counted down to zero","Reminder not reset after the last service","Several schedule items falling due together, such as filters, plugs and fluids","Mileage counter set to the wrong interval at the last reset","On Ford and Lincoln, a powertrain or electronic throttle fault using the same wrench symbol"],"guides":[],"codes":["P2111","P2135"]},
{"id":"oil-change-light","name":"Oil change due light","aka":["Change engine oil soon","Oil change reminder","Oil life light","Engine oil life monitor","Oil change required"],"color":"amber","sev":"check","icon":"<path d=\"M24 12c0 0 7 9.5 7 15a7 7 0 0 1-14 0c0-5.5 7-15 7-15z\"/><path d=\"M38 24a14 14 0 1 1-6-11.5\"/><path d=\"M32 6v7h-7\"/>","meaning":"The car's reminder system says the engine oil has reached the end of its useful life and an oil and filter change is due. It is a counter or an oil life calculation, not a sign that something has broken.","drive":"Yes. The car drives exactly the same with it on, and nothing is failing. Book the oil change within the next few hundred miles rather than the next few thousand. The one thing to do now is check the oil level on the dipstick, because a car that is also low on oil needs attention sooner.","todo":["Check the oil level on the dipstick with the engine off, cool and the car on level ground.","Press the trip or info button to read the oil life or miles-to-service figure, and write it down.","Get the oil and filter changed, using the grade listed on the filler cap or in the manual.","Make sure the reminder is reset afterwards, or the car keeps counting from the wrong point."],"causes":["Mileage or time interval for an oil change reached","Oil life monitor counted down to zero","Reminder never reset after the last oil change","Short trips, towing or long idling shortening the calculated oil life","Low oil level or a slow oil leak on cars with an oil level sensor","Oil level or oil quality sensor fault"],"guides":[],"codes":[]},
{"id":"oil-level-light","name":"Low engine oil level light","aka":["Low oil level warning","Engine oil level low","Add oil light","Oil level light"],"color":"amber","sev":"soon","icon":"<path d=\"M8 20h6l3-3h8l3 3 14-6 1 2-12 13H11l-3-3z\"/><path d=\"M21 17v-3M18 14h6\"/><path d=\"M8 20l-4-2v6l4 2\"/><path d=\"M14 37c2.5 0 3.5-2 6-2s3.5 2 6 2 3.5-2 6-2 3.5 2 6 2\"/>","meaning":"There is not enough engine oil in the sump. The oil that is left is still circulating, so this is a warning that you are getting close to trouble, not a sign that damage is already happening. It is not the same as the red oil pressure light, which means the oil is no longer being pushed through the engine and the engine must be shut off at once.","drive":"For a short distance, yes, but treat it as today's job, not next month's. Keep the trip gentle and short, add the right oil as soon as you can, and do not keep driving for days on a low level, because low oil turns into low oil pressure and then into engine damage. If the light is red, or the oil can symbol comes on with a buzzer or a STOP ENGINE message, pull over safely and switch off instead.","todo":["Park on level ground, switch the engine off and wait about ten minutes for the oil to drain back down.","Check the dipstick, or the oil level display in the dash menu on cars that have no dipstick.","Add the oil type printed on the filler cap or in the manual, about half a quart at a time, rechecking until the level is between the two marks. Do not fill past the upper mark.","If the level was already correct, or it drops again within a week or two, have the car checked for a leak or for oil consumption."],"causes":["Normal oil consumption since the last oil change","An engine that burns oil through worn rings, valve guides or a failing PCV system","An oil leak at the valve cover, oil pan, filter housing or a seal","Underfilled at the last oil change, or the wrong grade used","A faulty oil level sensor reading low when the oil is fine","Very long intervals between oil changes with no top-ups"],"guides":["burning-oil-low-oil-level","oil-leak"],"codes":[]},
{"id":"stability-control-off-light","name":"Stability control off light (ESC OFF)","aka":["ESC OFF light","VSC OFF light","TCS OFF light","DSC OFF light","Traction control off light"],"color":"amber","sev":"check","icon":"<path d=\"M13 29h22l-3-6-3-3H19l-3 3z\"/><path d=\"M16 23h16\"/><circle cx=\"18\" cy=\"32\" r=\"2.4\"/><circle cx=\"30\" cy=\"32\" r=\"2.4\"/><path d=\"M8 14c4-3.5 8 3.5 12 0s8 3.5 12 0 6 1 6 1\"/><text x=\"24\" y=\"45\" text-anchor=\"middle\" font-family=\"system-ui,Arial,sans-serif\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\">OFF</text>","meaning":"The system that catches a skid and stops the wheels spinning is switched off. Either someone pressed the off button, or the car shut the system down itself because it found a fault.","drive":"Yes, the car still steers and brakes normally. But it will not help you if the back end slides, so take it easy in rain, snow and on gravel, and get it looked at if the light came on by itself.","todo":["Find the off button (often near the gear lever or left of the steering wheel) and press it to switch the system back on.","If that does nothing, shut the engine off and restart; most cars turn the system back on at every start.","Check whether the ABS, brake or check engine light is on as well, and tell the shop which ones.","If the light will not go out, have the codes read from the brake and stability modules."],"causes":["The off button was pressed, on purpose or by accident","A drive mode or four-wheel-drive low range turned the system off","Wheel speed sensor fault","Steering angle sensor needs calibrating, often after battery or steering work","Mismatched, odd-size or badly worn tires, or a compact spare fitted","ABS or stability control module fault, or a blown fuse"],"guides":[],"codes":[]},
{"id":"washer-fluid-light","name":"Low washer fluid light","aka":["Low washer fluid warning","Washer fluid light","Low windshield washer fluid"],"color":"amber","sev":"info","icon":"<path d=\"M12 32c0-10 5-17 12-17s12 7 12 17z\"/><path d=\"M12 32h24\"/><path d=\"M8 20c2-1 4-1 6 0M6 26c2-1 4-1 6 0M10 14c2-1 4-1 6 0\"/>","meaning":"The windshield washer bottle is nearly empty, so there may be little or no fluid left to clean the glass. It says nothing about the engine or anything else mechanical.","drive":"Yes. This is the least urgent light on the dash. The only real risk is not being able to clear road salt, dust or bug splatter off the glass, which can leave you half blind on a sunny or wet highway, so fill it at the next chance.","todo":["Top the washer bottle up with washer fluid, not plain water.","If the light stays on with a full bottle, the level sensor or its wiring is likely at fault.","If the bottle empties again within days, look for a leak at the tank, the pump seal or a split hose.","In freezing weather, use winter-rated fluid so the tank and lines do not freeze."],"causes":["Bottle simply run low from normal use","Washer fluid level sensor stuck or failed","Cracked or leaking washer bottle","Leaking washer pump seal or split hose","Damaged wiring or connector at the sensor","Fluid frozen in the tank in cold weather"],"guides":[],"codes":[]},
{"id":"electronic-parking-brake-light","name":"Electronic parking brake fault light","aka":["EPB light","Electric parking brake fault","Park brake malfunction","Amber P light","Auto hold fault light"],"color":"amber","sev":"soon","icon":"<circle cx=\"21\" cy=\"24\" r=\"11\"/><text x=\"21\" y=\"30\" text-anchor=\"middle\" font-family=\"system-ui,Arial,sans-serif\" font-size=\"16\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\">P</text><path d=\"M39 13v14M39 33v.5\"/>","meaning":"The car has found a fault in the electric parking brake, the one worked by a small button or switch instead of a lever. The brake may not hold the car, or may not fully release.","drive":"You can usually drive, because this brake is only for parking, not for stopping. Expect it not to hold on a slope: leave the car in Park, or in gear on a manual, and turn the wheels into the curb. If a rear wheel drags, smells hot or the car will not move freely, stop and have it towed on a flatbed.","todo":["Park, then press the brake pedal and cycle the parking brake switch off and on twice to see if the light clears.","If the car is a plug-in or electric, make sure the charging cable is unplugged.","Have the 12-volt battery tested, as a weak battery sets this light off on many cars.","If the brake will not release or a rear wheel drags, don't force it: get it towed to a shop."],"causes":["Failed actuator motor on a rear brake caliper","Weak or dying 12-volt battery","Broken parking brake switch","Worn rear brake pads or a stuck caliper","Damaged wiring or a corroded connector at a rear wheel","Parking brake or ABS control module fault"],"guides":[],"codes":[]},
{"id":"epc-light","name":"EPC light","aka":["Electronic power control light","EPC warning light","VW EPC light","Audi EPC light"],"color":"amber","sev":"soon","icon":"<rect x=\"5\" y=\"14\" width=\"38\" height=\"20\" rx=\"5\"/><text x=\"24\" y=\"29\" text-anchor=\"middle\" font-family=\"system-ui,Arial,sans-serif\" font-size=\"14\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\">EPC</text>","meaning":"EPC stands for electronic power control, the system that runs the electronic gas pedal and throttle on Volkswagen, Audi, Seat and Skoda cars. The light means a fault has been stored somewhere in that system, which also takes in the brake pedal switch and, on many models, the stability and steering sensors.","drive":"If the car still accelerates normally, drive it gently and book a shop within a day or two. If power is held back, the engine will not rev freely and the car may feel flat or stuck in gear: stay off the highway, and drive slowly straight to a shop or have it towed. If EPC appears with a red light, with the brake lights not working, or with heavy shaking, stop and get it looked at before going further.","todo":["Park safely, switch the engine off for half a minute, then restart and see if the light clears.","Have someone check your brake lights work, as a failed brake pedal switch is the most common cause.","Notice whether the car has lost power and whether the ABS, stability or check engine light is also on.","Get all the control units scanned, not just the engine, because a basic code reader often shows nothing."],"causes":["Failed brake pedal (brake light) switch","Dirty or failed throttle body","Misfire from worn ignition coils or spark plugs","Mass airflow sensor fault","Accelerator pedal position sensor","ABS wheel speed or brake pressure sensor"],"guides":[],"codes":[]},
{"id":"esp-bas-light","name":"ESP BAS warning light","aka":["ESP/BAS light","ESP BAS light","Electronic Stability Program light","Brake Assist System light"],"color":"amber","sev":"soon","icon":"<rect x=\"4\" y=\"11\" width=\"40\" height=\"26\" rx=\"5\"/><text x=\"24\" y=\"23\" text-anchor=\"middle\" font-family=\"system-ui,Arial,sans-serif\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\">ESP</text><text x=\"24\" y=\"34\" text-anchor=\"middle\" font-family=\"system-ui,Arial,sans-serif\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\">BAS</text>","meaning":"The computer that keeps the car from sliding in a corner (ESP) and adds extra braking power in a panic stop (BAS) has found a fault and switched itself off. Your ordinary brakes and steering still work.","drive":"Usually yes for a short while. The car drives and stops normally, but nothing will catch a skid for you and you get no extra boost in an emergency stop, so drive gently and get it checked within a few days. If the red brake warning light comes on with it, or the pedal feels soft or long, stop driving and have it towed.","todo":["Have someone watch behind the car while you press the brake pedal. No brake lights points straight at a failing brake light switch, a very common cause.","Check the brake fluid level in the see-through reservoir with the engine off and cool.","Restart the car once. If it came on during a slow, struggling start, the battery may be weak.","If it stays on, have the ABS and stability codes read; a basic code reader often cannot see them."],"causes":["Failing brake light switch","Wheel speed sensor or damaged sensor wiring","Steering angle sensor out of calibration","Weak battery or low system voltage","ABS or stability control module fault","Low brake fluid or badly worn brakes"],"guides":[],"codes":[]},
{"id":"exhaust-emission-light","name":"Exhaust emission system light","aka":["Exhaust system light","Emission system warning light","Exhaust gas warning light","EML"],"color":"amber","sev":"soon","icon":"<rect x=\"12\" y=\"22\" width=\"24\" height=\"10\" rx=\"5\"/><path d=\"M36 27h6\"/><path d=\"M12 27H6\"/><path d=\"M18 18c0-3 4-3 4-6s-3-3-3-3M27 18c0-3 4-3 4-6s-3-3-3-3\"/>","meaning":"Something in the exhaust or emissions system is not doing its job. On many European and some Asian cars this is a separate warning from the check engine light, so the car can tell you the trouble is in the exhaust.","drive":"Usually yes, gently, for a week or two while you book it in, as long as the light is steady and the car feels normal. If it is flashing, or the car has dropped into reduced power, drive straight to a shop: a flashing light means the engine is misfiring and raw fuel is cooking the catalytic converter.","todo":["Notice whether the light is steady or flashing, and whether the car has lost power.","Get the codes read. Many parts stores do it free, and the code number points straight at the part.","Book the repair rather than waiting. A cheap sensor left alone often takes the catalytic converter with it.","On a diesel, check the exhaust fluid level, because low or wrong DEF sets this warning too."],"causes":["Oxygen (lambda) sensor","Exhaust leak or loose clamp ahead of a sensor","EGR valve clogged with soot","NOx sensor on a diesel","Worn out catalytic converter","Misfire from spark plugs or ignition coils"],"guides":[],"codes":[]},
{"id":"parking-brake-light","name":"Parking brake light","aka":["Handbrake light","Emergency brake light","Park brake reminder","Red P light","BRAKE light"],"color":"red","sev":"soon","icon":"<circle cx=\"24\" cy=\"24\" r=\"10\"/><text x=\"24\" y=\"29\" text-anchor=\"middle\" font-family=\"system-ui,Arial,sans-serif\" font-size=\"15\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\">P</text><path d=\"M9 16a16 16 0 0 0 0 16M39 16a16 16 0 0 1 0 16\"/>","meaning":"Your parking brake is applied, or the car thinks it is. On most cars the same red lamp also warns about the brake system itself, so if it stays on with the brake fully released, treat it as a brake problem.","drive":"Release the parking brake and the light should go out within a second or two. If it goes out, you are fine to drive. If it stays on with the brake released, or the pedal feels soft or sinks toward the floor, stop driving and have the brakes checked or the car towed.","todo":["Push the pedal or button down, or drop the lever all the way, and watch whether the light goes out.","If the light stays on, check the brake fluid level in the see-through reservoir under the hood.","Drive a short distance and see whether a rear wheel smells hot or the car feels like it is being held back.","If the fluid is low or the pedal feels soft, do not drive it: have it looked at or towed."],"causes":["Parking brake not fully released","Sticking or misadjusted parking brake switch","Low brake fluid from worn pads or a leak","Seized or stretched parking brake cable","Faulty fluid level sensor in the reservoir cap","A brake system fault sharing the same red lamp"],"guides":[],"codes":[]},
{"id":"slip-indicator-light","name":"SLIP and VDC OFF indicators","aka":["SLIP light","VDC OFF light","Vehicle Dynamic Control light","Nissan traction control light"],"color":"amber","sev":"check","icon":"<path d=\"M9 31c4-5 8 5 12 0s8 5 12 0 6 2 6 2\"/><text x=\"24\" y=\"20\" text-anchor=\"middle\" font-family=\"system-ui,Arial,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" stroke=\"none\">SLIP</text>","meaning":"SLIP blinking as you drive means Nissan's Vehicle Dynamic Control is working to stop a wheel spinning. If SLIP stays on steady, usually alongside VDC OFF, the system has shut down, either because the VDC OFF button was pressed or because it found a fault.","drive":"Yes, carefully, in normal conditions. The car drives, steers and brakes as usual but nothing will catch a skid for you, so take extra care in rain, snow, gravel and on fast bends. If the ABS light or the check engine light is on with it, get it looked at soon rather than later.","todo":["Look for the VDC OFF button, usually low on the dash or near the shifter, and press it to switch the system back on, then restart the car.","If the lights appeared right after a battery change, jump start or flat battery, drive straight above about 10 mph for at least ten minutes so the system can relearn.","Check the tire pressures against the sticker in the driver's door opening, and that all four tires are the same size and not badly worn.","If the lights stay on, or the check engine light is on too, have the ABS and VDC codes read; a wheel speed sensor is the usual culprit."],"causes":["VDC switched off by the button, or 4WD in low range","Wheel speed sensor or damaged sensor wiring","Steering angle sensor needing a relearn after a battery disconnect","Weak battery or low system voltage","Mismatched, worn or wrong-size tires, or badly worn brake parts","An engine fault with the check engine light, which shuts VDC down"],"guides":[],"codes":[]},
{"id":"water-in-fuel-light","name":"Water in fuel light (diesel)","aka":["Water in fuel filter light","WIF light","Drain fuel filter light","Water separator light"],"color":"amber","sev":"soon","icon":"<rect x=\"14\" y=\"8\" width=\"20\" height=\"28\" rx=\"4\"/><path d=\"M14 26h20\"/><path d=\"M24 29c0 0 4 4.5 4 7a4 4 0 0 1-8 0c0-2.5 4-7 4-7z\"/><path d=\"M20 8V5M28 8V5\"/>","meaning":"Water has collected in the diesel fuel filter or water separator. Water in diesel does not burn, and it rusts and scores the injectors and the high-pressure pump.","drive":"Short, gentle trips are usually fine, but treat it as a same-day job. Drain the separator or get the filter changed before any long drive, and stop driving if the engine starts running rough, losing power or blowing white smoke.","todo":["Drain the water separator if your truck has a drain valve. Most diesel pickups do, and the owner's manual shows where it is.","Look up 'water in fuel' in the owner's manual. It says whether yours drains by hand, by a dash button, or only at a shop.","Think about where you last filled up. One bad tank of diesel is the usual cause of a sudden warning.","If the light stays on after a proper drain, have the fuel filter replaced and the water-in-fuel sensor tested."],"causes":["Water collected in the filter or separator from normal use","Contaminated diesel from a filling station","Fuel filter long past its service life","Moisture condensing in a tank that sits part empty","Faulty water-in-fuel sensor","Cracked fuel cap seal or leaking filter housing letting water in"],"guides":[],"codes":[]},
{"id":"wrench-light","name":"Wrench light","aka":["Powertrain malfunction light","Ford wrench light","Reduced engine power light","Service wrench light"],"color":"amber","sev":"soon","icon":"<path d=\"M13 37l15-15\"/><path d=\"M28 22a8 8 0 1 1 10-10l-6 6 4 4 6-6a8 8 0 0 1-14 6z\"/>","meaning":"The computer that runs the engine and transmission has found a fault it cannot work around, often in the electronic throttle, the transmission or the all-wheel-drive system. On Ford and Lincoln it usually comes with a message on the dash and the car may cut your power on purpose to protect itself.","drive":"Short answer: only as far as you need to. If the car drives and shifts normally you can finish a local trip and book a shop in the next day or two. If the pedal feels dead, the car will not pick up speed, or the gears bang and slip, stay off the highway and drive gently straight to a shop, or have it towed. Do not tow a trailer or load it up while this light is on.","todo":["Pull over somewhere safe, shut the engine off, wait half a minute and restart it.","Read the message on the dash display and write the exact wording down.","Notice whether power is reduced or shifting feels wrong, and whether any other light is on.","Get the codes read from every computer, not just the engine, as soon as you can."],"causes":["Electronic throttle body fault","Low or burnt transmission fluid","Transmission solenoid or speed sensor","Accelerator pedal position sensor","Turbo boost control fault on EcoBoost engines","Loose wiring, corroded connector or weak charging"],"guides":[],"codes":[]}
];
